sp_widget.client_script:
function ($scope, $sce) {
	var c = this;
	c.html = $sce.trustAsHtml(c.options.html);
	$scope.$watch('c.options.html',function(){
		c.html = $sce.trustAsHtml(c.options.html);
	})
}

sp_widget.css:
.campusdesk-hero {
  background: linear-gradient(135deg, #071b2b 0%, #0b3045 55%, #123f50 100%);
  min-height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 55px 30px;
  border-radius: 0 0 18px 18px;
  box-sizing: border-box;
}

.campusdesk-hero-content {
  width: 100%;
  max-width: 900px;
  text-align: center;
  color: #ffffff;
}

.campusdesk-badge {
  display: inline-block;
  padding: 7px 16px;
  border: 1px solid rgba(255,255,255,0.3);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 1.5px;
  margin-bottom: 18px;
}

.campusdesk-hero h1 {
  margin: 0;
  font-size: 42px;
  font-weight: 700;
  line-height: 1.2;
}

.campusdesk-hero h1 span {
  color: #8fd14f;
}

.campusdesk-subtitle {
  max-width: 700px;
  margin: 18px auto 28px;
  font-size: 17px;
  line-height: 1.6;
  color: rgba(255,255,255,0.85);
}

.campusdesk-search {
  display: flex;
  max-width: 700px;
  margin: 0 auto;
  background: #ffffff;
  border-radius: 10px;
  padding: 6px;
  box-shadow: 0 8px 25px rgba(0,0,0,0.2);
}

.campusdesk-search input {
  flex: 1;
  border: none;
  outline: none;
  padding: 14px 16px;
  font-size: 15px;
  color: #333333;
}

.campusdesk-search button {
  border: none;
  border-radius: 7px;
  padding: 0 22px;
  background: #8fd14f;
  color: #071b2b;
  font-weight: 700;
  cursor: pointer;
}

.campusdesk-search button:hover {
  opacity: 0.9;
}

.campusdesk-quick-text {
  margin-top: 18px;
  font-size: 13px;
  color: rgba(255,255,255,0.65);
}

@media (max-width: 600px) {
  .campusdesk-hero {
    padding: 40px 18px;
  }

  .campusdesk-hero h1 {
    font-size: 30px;
  }

  .campusdesk-subtitle {
    font-size: 15px;
  }

  .campusdesk-search {
    flex-direction: column;
    padding: 8px;
  }

  .campusdesk-search button {
    padding: 12px;
  }
}
